"""sklearn.utils.parallel — parallel-execution helpers.

Wraps joblib when available, falls back to serial execution otherwise."""


try:
    import joblib
    Parallel = joblib.Parallel
    def delayed(func):
        return joblib.delayed(func)
except ImportError:
    # Serial fallback — runs jobs inline.
    class Parallel:
        """In-process serial fallback for joblib.Parallel."""

        def __init__(self, n_jobs=None, **kwargs):
            self.n_jobs = n_jobs

        def __call__(self, iterable):
            out = []
            for item in iterable:
                # ``delayed`` produces a callable; otherwise pass through.
                out.append(item() if callable(item) else item)
            return out

    def delayed(func):
        def _wrapper(*args, **kwargs):
            return lambda: func(*args, **kwargs)
        return _wrapper



# Make ``Parallel`` and ``delayed`` available at module scope regardless of
# which import branch executed above.
__all__ = ['Parallel', 'delayed']
